{
  "name": "TUN 虚拟网络接口工具",
  "name_en": "TUN Network Interface Utility",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于创建和管理 TUN 虚拟网络接口。在实验环境中，它可用于配置接口、分配或删除 IPv6 地址、执行连通性测试，并向虚拟隧道写入网络数据包，以支持网络通信调试与协议联调。",
  "description_en": "This is a non-physical software component for creating and managing a TUN virtual network interface. In lab and test environments, it is used to configure the interface, add or remove IPv6 addresses, run connectivity checks, and write network packets into the virtual tunnel for network communication testing and protocol integration.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭该非物理 TUN 隧道接口。",
      "description_en": "Close the non-physical TUN tunnel interface."
    },
    {
      "action_name": "auto-command",
      "description": "执行与网络接口管理相关的系统命令。",
      "description_en": "Execute a system command related to network interface management."
    },
    {
      "action_name": "auto-ifconfig",
      "description": "配置虚拟网络接口状态和地址参数。",
      "description_en": "Configure the virtual network interface state and address settings."
    },
    {
      "action_name": "auto-ping6",
      "description": "对目标 IPv6 地址执行连通性测试。",
      "description_en": "Ping a target IPv6 address to test connectivity."
    },
    {
      "action_name": "auto-addr_add",
      "description": "向 TUN 虚拟网络接口添加 IPv6 地址。",
      "description_en": "Add an IPv6 address to the TUN virtual network interface."
    },
    {
      "action_name": "auto-addr_del",
      "description": "从 TUN 虚拟网络接口删除 IPv6 地址。",
      "description_en": "Delete an IPv6 address from the TUN virtual network interface."
    },
    {
      "action_name": "auto-write",
      "description": "向 TUN 虚拟网络接口写入或发送网络数据包。",
      "description_en": "Write or send a network packet to the TUN virtual network interface."
    }
  ],
  "tag_hints": [
    "TUN virtual interface",
    "IPv6 networking",
    "network tunnel",
    "packet injection",
    "connectivity testing",
    "ifconfig management",
    "virtual network adapter"
  ]
}

